SELECT OBJECT_SCHEMA_NAME(i.object_id) SchemaName,OBJECT_NAME(i.object_id) TableName,i.name KeyName,i.is_primary_key IsPrimaryKey,i.is_unique IsUnique,COL_NAME(ic.object_id,ic.column_id) ColumnName,ic.key_ordinal KeyOrdinal FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id WHERE i.is_unique=1 AND ic.key_ordinal>0 ORDER BY SchemaName,TableName,KeyName,KeyOrdinal